import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"让漂流钓鱼更省心：XPlus 自动钓鱼设置指南","description":"一组用于尝试科技空岛漂流钓鱼的 XPlus 参考设置，含声音来源、收竿音效与重抛延迟。","frontmatter":{"title":"让漂流钓鱼更省心：XPlus 自动钓鱼设置指南","description":"一组用于尝试科技空岛漂流钓鱼的 XPlus 参考设置，含声音来源、收竿音效与重抛延迟。"},"headers":[],"relativePath":"guides/xplus-autofish.md","filePath":"guides/xplus-autofish.md"}`),a={name:`guides/xplus-autofish.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="让漂流钓鱼更省心-xplus-自动钓鱼设置指南" tabindex="-1">让漂流钓鱼更省心：XPlus 自动钓鱼设置指南 <a class="header-anchor" href="#让漂流钓鱼更省心-xplus-自动钓鱼设置指南" aria-label="Permalink to “让漂流钓鱼更省心：XPlus 自动钓鱼设置指南”">​</a></h1><p>空中漂流钓鱼是科技空岛里获取材料的一种方式。如果你已经在使用 XPlus，也可以尝试它的自动钓鱼功能，减少反复收竿和抛竿的操作。</p><p>下面是一组用于尝试服务器漂流玩法的<strong>参考设置</strong>，并非所有 XPlus 版本通用的官方配置。</p><h2 id="_1-打开自动钓鱼设置" tabindex="-1">1. 打开自动钓鱼设置 <a class="header-anchor" href="#_1-打开自动钓鱼设置" aria-label="Permalink to “1. 打开自动钓鱼设置”">​</a></h2><p>默认按 <strong>V</strong> 打开 XPlus 设置，找到自动钓鱼选项。若按键没有反应，先到游戏的按键设置里检查绑定和冲突。</p><p>不同版本可能将“声音检测”放在检测方式或兼容性设置中，选项名称也可能不同。</p><h2 id="_2-按表调整" tabindex="-1">2. 按表调整 <a class="header-anchor" href="#_2-按表调整" aria-label="Permalink to “2. 按表调整”">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>建议值</th></tr></thead><tbody><tr><td>启用自动钓鱼</td><td>开启</td></tr><tr><td>检测方式／使用声音检测</td><td>声音检测／开启</td></tr><tr><td>声音检测来源</td><td>服务器声音数据包</td></tr><tr><td>持续模式</td><td>关闭</td></tr><tr><td>收竿音效</td><td><code>minecraft:entity.fishing_bobber.splash</code></td></tr><tr><td>收竿延迟</td><td>1 毫秒或允许的最小值</td></tr><tr><td>重新投掷延迟</td><td>建议 1000～1500 毫秒</td></tr><tr><td>开放水域检测</td><td>可以关闭，避免空钓时出现水域提醒</td></tr><tr><td>音效距离参考对象（如果存在）</td><td>浮漂</td></tr></tbody></table><p>收竿音效可从下方复制：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>minecraft:entity.fishing_bobber.splash</span></span></code></pre></div><p>找不到“服务器声音数据包”或“浮漂”等选项时，不要随意把其他设置当成同一功能；先核对所用版本是否提供它。</p><h2 id="_3-先观察几次-再继续使用" tabindex="-1">3. 先观察几次，再继续使用 <a class="header-anchor" href="#_3-先观察几次-再继续使用" aria-label="Permalink to “3. 先观察几次，再继续使用”">​</a></h2><ol><li>确认手持的是专用漂流鱼竿，站在安全、空旷的位置。</li><li>手动抛出第一竿，观察咬钩后能否收竿、获得掉落并重新抛竿。</li><li>若反复空收或不动作，先暂停辅助功能，手动试钓，区分基础玩法与辅助设置的问题。</li><li>结合当前客户端版本调整；附近玩家的浮漂和声音也可能影响识别。</li></ol><p>不了解专用竿或等级规则，先看 <a href="./../skyblock/fishing.html">漂流钓鱼指南</a>。想确认是否钓对了奖池，查 <a href="./../skyblock/fishing-rewards.html">六级完整掉落表</a>。</p><h2 id="适用范围与来源" tabindex="-1">适用范围与来源 <a class="header-anchor" href="#适用范围与来源" aria-label="Permalink to “适用范围与来源”">​</a></h2><p>作者维护的 <a href="https://modrinth.com/mod/x-plus-autofish" target="_blank" rel="noreferrer">XPlus Autofish 项目页</a> 介绍了默认 V 键、声音检测与重抛延迟等功能；<a href="https://github.com/Wudji/XPlus-AutoFish/blob/fabric-26.x/src/main/resources/assets/autofish/lang/en_us.json" target="_blank" rel="noreferrer">作者仓库中的选项说明（fabric-26.x 分支）</a> 可核对声音数据包来源与浮漂参考点的含义。该分支不等于科技空岛 1.21.1 客户端使用的版本，<strong>来源用于核对功能，不表示本表已获得官方或服务器的效果保证</strong>。</p><div class="info custom-block"><p class="custom-block-title">使用前记住</p><p>不同版本的菜单与行为可能不同；钓鱼效果也受当前游戏环境和服务器机制影响。使用辅助功能须遵守服务器规则，自动钓鱼不代表每次都能成功钓取。</p></div>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};